/**
 * Milestone rows plus the issue-side queries that only milestones need
 * (progress counts, bulk moves). Every method takes `orgId` first.
 */
import { and, count, eq, inArray, isNull, notInArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toIssue, toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of a project, closed ones included, oldest first. */
export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(sql`${milestones.rowid}`)
    .all();
  return rows.map(toMilestone);
}

export async function insertMilestone(input: {
  orgId: OrgId;
  projectId: ProjectId;
  name: string;
  targetDate: IsoTimestamp | null;
}): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: { name?: string; targetDate?: IsoTimestamp | null },
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.targetDate === undefined ? {} : { targetDate: patch.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();
  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

export async function setMilestoneClosedAt(
  orgId: OrgId,
  milestoneId: MilestoneId,
  closedAt: IsoTimestamp | null,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();
  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/** Total / open / closed counts over live issues, keyed by milestone id. */
export async function progressForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ReadonlyMap<string, MilestoneProgress>> {
  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      closed: sql<number>`sum(case when ${issues.status} in ('done','canceled') then 1 else 0 end)`,
      total: count(),
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        isNull(issues.archivedAt),
        sql`${issues.milestoneId} is not null`,
      ),
    )
    .groupBy(issues.milestoneId)
    .all();

  const map = new Map<string, MilestoneProgress>();
  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const closed = Number(row.closed ?? 0);
    map.set(row.milestoneId, {
      total: row.total,
      open: row.total - closed,
      closed,
    });
  }
  return map;
}

/** Live issues of the milestone that are not done or canceled. */
export async function listOpenLiveIssues(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.milestoneId, milestoneId),
        isNull(issues.archivedAt),
        notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
      ),
    )
    .all();
  return rows.map((row) => toIssue(row));
}

export async function moveIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
  milestoneId: MilestoneId | null,
): Promise<void> {
  if (issueIds.length === 0) return;
  getDb()
    .update(issues)
    .set({ milestoneId, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])),
    )
    .run();
}
