  assertNotArchived("Project", project.id, project);

  const siblings = await milestoneRepo.listMilestonesForProject(
    input.orgId,
    input.projectId,
  );
  assertNameFree(siblings, input.name, null);
  assertRoomForOpen(siblings);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: input.projectId,
    name: input.name,
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const { milestone } = await loadForWrite(actor, input.orgId, input.milestoneId);

  if (input.name !== undefined) {
    const siblings = await milestoneRepo.listMilestonesForProject(
      input.orgId,
      milestone.projectId,
    );
    assertNameFree(siblings, input.name, milestone.id);
  }

  return milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    name: input.name,
    targetDate: input.targetDate,
  });
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const { milestone } = await loadForWrite(actor, input.orgId, input.milestoneId);
  if (milestone.closedAt !== null) {
    throw new MilestoneStateError(
      "closed",
      `Milestone ${milestone.id} is already closed`,
    );
  }

  const targetId = input.moveOpenIssuesTo;
  if (targetId !== null) {
    if (targetId === milestone.id) {
      throw new NotFoundError("Milestone", targetId);
    }
    const target = requireFound(
      await milestoneRepo.findMilestoneById(input.orgId, targetId),
      "Milestone",
      targetId,
    );
    if (target.projectId !== milestone.projectId) {
      throw new NotFoundError("Milestone", targetId);
    }
    if (target.closedAt !== null) {
      throw new MilestoneStateError("closed", `Milestone ${targetId} is closed`);
    }
  }

  const moving = await milestoneRepo.listOpenLiveIssues(input.orgId, milestone.id);
  const movedIssueIds = moving.map((issue) => issue.id);
  await milestoneRepo.moveIssues(input.orgId, movedIssueIds, targetId);

  const closed = await milestoneRepo.setMilestoneClosedAt(
    input.orgId,
    milestone.id,
    toIsoTimestamp(new Date()),
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: targetId,
    movedIssueIds,
  });

  for (const issue of moving) {
    if (issue.assigneeId === null) continue;
    await notify(input.orgId, "issue_milestone_changed", [issue.assigneeId], {
      title: "An issue changed milestone",
      body: `Issue ${issue.id} left milestone ${closed.name}`,
      href: `/issues/${issue.id}`,
      actorId: actor.userId,
    });
  }

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const { milestone } = await loadForWrite(actor, orgId, milestoneId);
  if (milestone.closedAt === null) {
    throw new MilestoneStateError(
      "already_open",
      `Milestone ${milestone.id} is already open`,
    );
  }

  const siblings = await milestoneRepo.listMilestonesForProject(
    orgId,
    milestone.projectId,
  );
  assertRoomForOpen(siblings);

  const reopened = await milestoneRepo.setMilestoneClosedAt(
    orgId,
    milestone.id,
    null,
  );

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date,
): MilestoneWithProgress {
  return {
    milestone,
    progress,
    overdue: isMilestoneOverdue(milestone, progress, now),
  };
}

/** Time of the target date, with milestones lacking one sorting last. */
function targetTime(milestone: Milestone): number {
  return milestone.targetDate === null
    ? Number.POSITIVE_INFINITY
    : new Date(milestone.targetDate).getTime();
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = await loadProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const now = new Date();
  const all = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  const progress = await milestoneRepo.progressForProject(orgId, projectId);

  // `all` is oldest-first and Array#sort is stable, so ties keep creation order.
  return [...all]
    .sort((a, b) => {
      const groupA = a.closedAt === null ? 0 : 1;
      const groupB = b.closedAt === null ? 0 : 1;
      if (groupA !== groupB) return groupA - groupB;
      const ta = targetTime(a);
      const tb = targetTime(b);
      return ta === tb ? 0 : ta < tb ? -1 : 1;
    })
    .map((m) => withProgress(m, progress.get(m.id) ?? NO_PROGRESS, now));
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await loadProject(orgId, milestone.projectId);
  assertCan(actor, "project:read", projectResource(project));

  const now = new Date();
  const progress = await milestoneRepo.progressForProject(
    orgId,
    milestone.projectId,
  );
  return withProgress(milestone, progress.get(milestone.id) ?? NO_PROGRESS, now);
}
